DROP TABLE IF EXISTS `recommendations_hotel`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `recommendations_hotel` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `name` varchar(200) NOT NULL,
  `description` longtext NOT NULL,
  `address` longtext NOT NULL,
  `phone` varchar(50) NOT NULL,
  `email` varchar(254) NOT NULL,
  `website` varchar(200) NOT NULL,
  `image_main` varchar(100) DEFAULT NULL,
  `image_gallery` json NOT NULL,
  `price_single` decimal(10,2) NOT NULL,
  `price_couple` decimal(10,2) NOT NULL,
  `price_executive` decimal(10,2) NOT NULL,
  `price_family` decimal(10,2) NOT NULL,
  `price_entire_hotel` decimal(10,2) DEFAULT NULL,
  `price_villa` decimal(10,2) DEFAULT NULL,
  `amenities` json NOT NULL,
  `rating` decimal(3,2) NOT NULL,
  `total_rooms` int NOT NULL,
  `check_in_time` varchar(20) NOT NULL,
  `check_out_time` varchar(20) NOT NULL,
  `cancellation_policy` longtext NOT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `destination_id` bigint NOT NULL,
  PRIMARY KEY (`id`),
  KEY `recommendations_hote_destination_id_1aeff40a_fk_recommend` (`destination_id`),
  CONSTRAINT `recommendations_hote_destination_id_1aeff40a_fk_recommend` FOREIGN KEY (`destination_id`) REFERENCES `recommendations_destination` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=118 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
