INSERT INTO `recommendations_hotel` VALUES (1,'Abbottabad Budget Inn','Affordable and clean accommodation perfect for budget travelers. Our inn provides basic amenities including comfortable beds, hot water, WiFi, and friendly staff. Located conveniently near local attractions and markets. Great value for money.','Main Road, Abbottabad, Pakistan','+92-375-7915297','info@abbottabadbudgetinn.com','https://www.abbottabadbudgetinn.com','','[]',2085.30,2946.30,4771.90,6301.40,NULL,NULL,'[\"WiFi\", \"Hot Water\", \"Parking\", \"Basic Breakfast\"]',3.71,14,'2:00 PM','10:00 AM','Free cancellation up to 24 hours before check-in. 50% refund for cancellations within 24 hours. No refund for no-shows.','2025-12-13 17:18:41.107066','2025-12-13 17:18:41.107100',425),(2,'Altit Fort Pearl Resort','A serene retreat nestled in nature offering cozy accommodation with breathtaking scenic views. Our resort features comfortable rooms, traditional cuisine restaurant, outdoor activities, bonfire evenings, and warm hospitality. Ideal for adventure seekers and nature lovers.','Main Road, Altit Fort, Pakistan','+92-335-9989022','info@altitfortpearlresort.com','https://www.altitfortpearlresort.com','','[]',3661.20,7072.80,7430.40,11653.20,97165.20,20353.20,'[\"WiFi\", \"Restaurant\", \"Bonfire\", \"Outdoor Activities\", \"Parking\", \"Garden\"]',3.92,39,'1:00 PM','11:00 AM','Free cancellation up to 24 hours before check-in. 50% refund for cancellations within 24 hours. No refund for no-shows.','2025-12-13 17:18:41.113479','2025-12-13 17:18:41.113500',257),(3,'Astola Island Lake View Resort','Tranquil lakeside resort offering peaceful accommodation with water views. Enjoy boating, fishing, lakeside dining, campfire nights, and water sports. Our resort features comfortable cottages, private beach area, and outdoor seating. Perfect for romantic getaways and family vacations.','Main Road, Astola Island, Pakistan','+92-356-5542261','info@astolaislandlakeviewresort.com','https://www.astolaislandlakev